package com.hiretrack.service;import com.hiretrack.entity.User;import com.hiretrack.repository.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;@Component public class CurrentUser{private final UserRepository repo;public CurrentUser(UserRepository r){repo=r;}public User get(){return repo.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}}